quizzes.question:
다음 프로그램의 결과로 알맞은 것은? 

class Animal: def __init__(self, name, age): self.name = name
       self.age = age
      def say(self):
        print(f"안녕하세요. 제 이름은 {self.name}이고, 나이는 {self.age}살 입니다.")

class Dog(Animal):
        def __init__(self, name, age, breed):
          super().__init__(name, age)
          self.breed = breed
        def say(self):
          print(f"안녕. 내 이름은 {self.name}이고, 나이는 {self.age}살!. 나는 {self.breed}!.")
wolf = Dog("늑대", 3, "허스키")
wolf.say()
